syntax:
struct StructName {
    MemberType memberName = default_value;
};

// Constructor can override default initializers if needed
StructName(int value) : memberName(value) {}

code_example:
#include <iostream>
struct B2 {
    int a = 13;
    int b = 42;
    B2() = default; // default constructor uses default member initializers
    B2(int x, int y) : a(x), b(y) {} // constructor overrides defaults
};
int main() {
    B2 obj1; // members initialized to 13 and 42 by default
    B2 obj2(7, 14); // members initialized to 7 and 14 via constructor
    std::cout << "obj1: " << obj1.a << ", " << obj1.b << std::endl;
    std::cout << "obj2: " << obj2.a << ", " << obj2.b << std::endl;
    return 0;
}
